const cloudReport=report,cloudAPI=api;
// Delete the processed report together with the video before deleting metadata.
api=async function(path,options={}){if(path==='/storage/v1/object/recordings'&&options.method==='DELETE'){const data=JSON.parse(options.body);for(const item of [...data.prefixes])if(item.endsWith('/recording'))data.prefixes.push(item.slice(0,-'recording'.length)+'report.json');options={...options,body:JSON.stringify(data)}}return cloudAPI(path,options)};
async function analysisRequest(id,method='GET'){await api('/auth/v1/user');const r=await fetch('/api/sessions/'+id+'/analysis',{method,headers:{Authorization:'Bearer '+cloudAuth.access_token,'Content-Type':'application/json'},...(method==='POST'?{body:JSON.stringify({consent:true})}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Analysis unavailable');return data}
function showCoaching(panel,data){const r=data.report;panel.innerHTML=`<span class="pill">AI CONTENT COACHING</span><h3>Your talk, reflected back.</h3><h4>Summary</h4><p>${esc(r.summary)}</p><h4>What worked</h4><ul>${r.strengths.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><h4>What to improve</h4><ul>${r.improvements.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><h4>Next rehearsal</h4><p>${esc(r.next_practice)}</p><h4>Limits of this report</h4><ul>${r.limitations.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><p style="font-size:10px">Based on a machine transcript. No visual or vocal-delivery analysis. Review for recognition errors.</p>`;const t=$('#report-transcript p');if(t)t.textContent=data.transcript;document.querySelectorAll('.status-line').forEach(n=>{if(n.textContent.startsWith('AI report'))n.querySelector('span').textContent='Saved privately';if(n.textContent.startsWith('Transcript'))n.querySelector('span').textContent='OpenAI transcript'})}
report=async function(id){await cloudReport(id);const session=sessions.find(x=>x.id===id);if(!session?.cloud||view!=='report'||!$('#playback'))return;const panel=document.createElement('section');panel.className='panel ai-coaching';panel.style.marginBottom='20px';$('.report-grid>div:last-child').prepend(panel);panel.innerHTML='<h3>Transcription & coaching</h3><p role="status">Checking report availability…</p>';try{const result=await analysisRequest(id);if(view!=='report'||!panel.isConnected)return;if(result.status==='ready'){showCoaching(panel,result);return}const response=await fetch('/api/ai-status');const status=await response.json();panel.innerHTML=`<h3>Transcription & coaching</h3><p>${status.configured?'Generate a transcript and specific suggestions for your talk’s content.':'AI setup is pending. A fresh server API key is required before processing can run.'}</p><p style="font-size:11px">With your permission, your saved recording is sent to OpenAI for transcription, and the transcript is used to write a coaching report. Results are saved privately in your account. AI processing supports recordings up to 24 MB.</p><label class="consent"><input type="checkbox" id="ai-consent"> Send this recording to OpenAI for transcription and coaching.</label><button class="primary" id="generate-ai" disabled style="margin-top:15px">Transcribe & coach</button><p id="ai-progress" role="status"></p>`;const consent=panel.querySelector('input'),button=panel.querySelector('button');consent.onchange=()=>button.disabled=!status.configured||!consent.checked||session.byte_size>24000000;if(session.byte_size>24000000)panel.querySelector('#ai-progress').textContent='This recording exceeds the 24 MB AI limit. Video playback is still available.';button.onclick=async()=>{button.disabled=true;consent.disabled=true;panel.querySelector('#ai-progress').textContent='Transcribing and writing your report… Keep this page open.';try{const data=await analysisRequest(id,'POST');if(panel.isConnected&&view==='report'){showCoaching(panel,data);toast('Transcript and coaching report saved privately.')}}catch(e){if(panel.isConnected){panel.querySelector('#ai-progress').textContent=e.message;button.disabled=false;button.textContent='Retry transcription & coaching';consent.disabled=false}}}}catch(e){panel.innerHTML='<h3>Transcription & coaching</h3><p>'+esc(e.message)+'</p>'}};
const aiStyles=document.createElement('style');aiStyles.textContent='.ai-coaching h4{font-size:12px;margin:20px 0 8px}.ai-coaching ul{padding-left:18px;font-size:12px;color:#71816d;line-height:1.8}.ai-coaching li{margin-bottom:9px}';document.head.appendChild(aiStyles);
const visionScript=document.createElement('script');visionScript.src='vision.js';document.body.appendChild(visionScript);
